SELECT
a.*
FROM visual_screen.vs_gallery_info a
where 1=1

    and a.id = #{params.id}


    and a.type = #{params.type}


    and a.title like concat(concat('%',#{params.title}),'%')


    and a.state = #{params.state}


    and a.business_id = #{params.business_id}

ORDER BY a.sort asc
LIMIT #{params.rows,jdbcType=INTEGER} OFFSET #{params.page,jdbcType=INTEGER}

SELECT
COUNT(*)
FROM visual_screen.vs_gallery_info a
where 1=1

    and a.id = #{params.id}


    and a.type = #{params.type}


    and a.title like concat(concat('%',#{params.title}),'%')


    and a.state = #{params.state}


    and a.business_id = #{params.business_id}

SELECT
*
FROM visual_screen.vs_gallery_info a
where 1=1

    and a.id = #{params.id}


    and a.type = #{params.type}


    and a.title like concat(concat('%',#{params.title}),'%')


    and a.state = #{params.state}


    and a.business_id = #{params.business_id}

ORDER BY a.sort asc
